const std = @import("std");

pub const IntPoint = struct {
    x: i32 = 0,
    y: i32 = 0,
};

pub const IntSize = struct {
    width: i32 = 0,
    height: i32 = 0,

    pub fn eql(self: IntSize, other: IntSize) bool {
        return self.width == other.width and self.height == other.height;
    }
};

pub const IntRect = struct {
    origin: IntPoint = .{},
    size: IntSize = .{},

    pub fn isEmpty(self: IntRect) bool {
        return self.size.width <= 0 or self.size.height <= 0;
    }
};

pub const FloatPoint = struct {
    x: f64 = 0,
    y: f64 = 0,
};

pub const FramesPerSecond = f64;
pub const PlatformPaintContextPtr = ?*anyopaque;
pub const AsyncReplyID = u64;

pub const LayerTreeContext = struct {
    identifier: u64 = 0,

    pub fn empty() LayerTreeContext {
        return .{};
    }
};

pub const Region = struct {
    rects: std.ArrayList(IntRect),

    pub fn init(allocator: std.mem.Allocator) Region {
        return .{
            .rects = std.ArrayList(IntRect).init(allocator),
        };
    }

    pub fn deinit(self: *Region) void {
        self.rects.deinit();
    }

    pub fn clear(self: *Region) void {
        self.rects.clearRetainingCapacity();
    }

    pub fn assignRect(self: *Region, rect: IntRect) !void {
        self.clear();
        try self.rects.append(rect);
    }

    pub fn unite(self: *Region, rect: IntRect) !void {
        if (!rect.isEmpty())
            try self.rects.append(rect);
    }

    pub fn subtract(self: *Region, rect: IntRect) void {
        var result = std.ArrayList(IntRect).init(self.rects.allocator);
        defer result.deinit();

        for (self.rects.items) |existing| {
            if (!rectanglesIntersect(existing, rect)) {
                result.append(existing) catch {};
                continue;
            }

            const left = IntRect{
                .origin = existing.origin,
                .size = .{
                    .width = @max(0, rect.origin.x - existing.origin.x),
                    .height = existing.size.height,
                },
            };

            const existing_right = existing.origin.x + existing.size.width;
            const rect_right = rect.origin.x + rect.size.width;
            const right = IntRect{
                .origin = .{
                    .x = @max(existing.origin.x, rect_right),
                    .y = existing.origin.y,
                },
                .size = .{
                    .width = @max(0, existing_right - @max(existing.origin.x, rect_right)),
                    .height = existing.size.height,
                },
            };

            const top = IntRect{
                .origin = .{
                    .x = @max(existing.origin.x, rect.origin.x),
                    .y = existing.origin.y,
                },
                .size = .{
                    .width = @max(0, @min(existing_right, rect_right) - @max(existing.origin.x, rect.origin.x)),
                    .height = @max(0, rect.origin.y - existing.origin.y),
                },
            };

            const existing_bottom = existing.origin.y + existing.size.height;
            const rect_bottom = rect.origin.y + rect.size.height;
            const bottom = IntRect{
                .origin = .{
                    .x = @max(existing.origin.x, rect.origin.x),
                    .y = @max(existing.origin.y, rect_bottom),
                },
                .size = .{
                    .width = @max(0, @min(existing_right, rect_right) - @max(existing.origin.x, rect.origin.x)),
                    .height = @max(0, existing_bottom - @max(existing.origin.y, rect_bottom)),
                },
            };

            if (!left.isEmpty())
                result.append(left) catch {};
            if (!right.isEmpty())
                result.append(right) catch {};
            if (!top.isEmpty())
                result.append(top) catch {};
            if (!bottom.isEmpty())
                result.append(bottom) catch {};
        }

        self.rects.clearRetainingCapacity();
        self.rects.appendSlice(result.items) catch {};
    }
};

fn rectanglesIntersect(a: IntRect, b: IntRect) bool {
    return a.origin.x < b.origin.x + b.size.width and
        a.origin.x + a.size.width > b.origin.x and
        a.origin.y < b.origin.y + b.size.height and
        a.origin.y + a.size.height > b.origin.y;
}

pub const UpdateInfo = struct {
    update_rect_bounds: IntRect = .{},
    view_size: IntSize = .{},
    device_scale_factor: f64 = 1.0,
    scroll_rect: IntRect = .{},
    update_rects: []const IntRect = &.{},
};

pub const BackingStore = struct {
    allocator: std.mem.Allocator,
    backing_size: IntSize,
    backing_device_scale_factor: f64,

    pub fn create(allocator: std.mem.Allocator, size: IntSize, device_scale_factor: f64) !*BackingStore {
        const backing_store = try allocator.create(BackingStore);
        backing_store.* = .{
            .allocator = allocator,
            .backing_size = size,
            .backing_device_scale_factor = device_scale_factor,
        };
        return backing_store;
    }

    pub fn destroy(self: *BackingStore) void {
        self.allocator.destroy(self);
    }

    pub fn size(self: *const BackingStore) IntSize {
        return self.backing_size;
    }

    pub fn deviceScaleFactor(self: *const BackingStore) f64 {
        return self.backing_device_scale_factor;
    }

    pub fn paint(self: *BackingStore, _: PlatformPaintContextPtr, _: IntRect) void {
        _ = self;
    }

    pub fn incorporateUpdate(self: *BackingStore, update_info: UpdateInfo) void {
        self.backing_size = update_info.view_size;
        self.backing_device_scale_factor = update_info.device_scale_factor;
    }
};

pub const Preferences = struct {
    accelerated_compositing_enabled: bool = false,
