pub const WebPageProxy = struct {
    visible: bool = true,
    running_process: bool = true,
    current_view_size: IntSize = .{},
    current_device_scale_factor: f64 = 1.0,
    current_display_id: ?u64 = null,
    page_preferences: Preferences = .{},
    in_accelerated_compositing_mode: bool = false,
    current_layer_tree_context: LayerTreeContext = .{},
    needs_display_region: ?Region = null,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) WebPageProxy {
        return .{
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *WebPageProxy) void {
        if (self.needs_display_region) |*region|
            region.deinit();
    }

    pub fn isViewVisible(self: *const WebPageProxy) bool {
        return self.visible;
    }

    pub fn hasRunningProcess(self: *const WebPageProxy) bool {
        return self.running_process;
    }

    pub fn viewSize(self: *const WebPageProxy) IntSize {
        return self.current_view_size;
    }

    pub fn deviceScaleFactor(self: *const WebPageProxy) f64 {
        return self.current_device_scale_factor;
    }

    pub fn displayID(self: *const WebPageProxy) ?u64 {
        return self.current_display_id;
    }

    pub fn nominalFramesPerSecondForDisplay(_: *const WebPageProxy, display_id: u64) ?FramesPerSecond {
        if (display_id == 0)
            return null;
        return 60.0;
    }

    pub fn preferences(self: *const WebPageProxy) *const Preferences {
        return &self.page_preferences;
    }

    pub fn enterAcceleratedCompositingMode(self: *WebPageProxy, layer_tree_context: LayerTreeContext) void {
        self.in_accelerated_compositing_mode = true;
        self.current_layer_tree_context = layer_tree_context;
    }

    pub fn exitAcceleratedCompositingMode(self: *WebPageProxy) void {
        self.in_accelerated_compositing_mode = false;
        self.current_layer_tree_context = .{};
    }

    pub fn updateAcceleratedCompositingMode(self: *WebPageProxy, layer_tree_context: LayerTreeContext) void {
        self.current_layer_tree_context = layer_tree_context;
    }

    pub fn setViewNeedsDisplay(self: *WebPageProxy, damage_region: Region) void {
        if (self.needs_display_region) |*existing|
            existing.deinit();
        self.needs_display_region = damage_region;
    }
};

pub const AsyncReplyHandler = *const fn (?*anyopaque, ?*anyopaque) void;

pub const Connection = struct {
    allocator: std.mem.Allocator,
    async_reply_handlers: std.AutoHashMap(AsyncReplyID, AsyncReplyHandler),

    pub fn init(allocator: std.mem.Allocator) Connection {
        return .{
            .allocator = allocator,
            .async_reply_handlers = std.AutoHashMap(AsyncReplyID, AsyncReplyHandler).init(allocator),
        };
    }

    pub fn deinit(self: *Connection) void {
        self.async_reply_handlers.deinit();
    }

    pub fn takeAsyncReplyHandler(self: *Connection, callback_id: AsyncReplyID) ?AsyncReplyHandler {
        return self.async_reply_handlers.fetchRemove(callback_id) orelse null;
    }
};

pub const TimerCallback = *const fn (*anyopaque) void;

pub const OneShotTimer = struct {
    active: bool = false,
    delay_nanoseconds: u64 = 0,
    context: ?*anyopaque = null,
    callback: ?TimerCallback = null,

    pub fn init(context: *anyopaque, callback: TimerCallback) OneShotTimer {
        return .{
            .context = context,
            .callback = callback,
        };
    }

    pub fn isActive(self: *const OneShotTimer) bool {
        return self.active;
    }

    pub fn stop(self: *OneShotTimer) void {
        self.active = false;
        self.delay_nanoseconds = 0;
    }

    pub fn startOneShot(self: *OneShotTimer, delay_nanoseconds: u64) void {
        self.active = true;
        self.delay_nanoseconds = delay_nanoseconds;
    }

    pub fn fire(self: *OneShotTimer) void {
        if (!self.active)
            return;

        self.active = false;
        if (self.context) |context| {
            if (self.callback) |callback|
                callback(context);
        }
    }
};

pub const CompletionHandler = *const fn () void;

pub const DrawingAreaProxyCoordinatedGraphics = struct {
    allocator: std.mem.Allocator,
    web_page: ?*WebPageProxy,
    web_process_proxy: *WebProcessProxy,
    backing_store: ?*BackingStore = null,
    layer_tree_context: LayerTreeContext = .{},
    last_sent_size: IntSize = .{},
    is_waiting_for_did_update_geometry: bool = false,
    in_force_update: bool = false,
    is_backing_store_discardable: bool = false,
    discard_backing_store_timer: OneShotTimer,
    drawing_monitor: ?*DrawingMonitor = null,
    identifier_value: u64 = 0,

    pub fn create(allocator: std.mem.Allocator, page: *WebPageProxy, web_process_proxy: *WebProcessProxy) !*DrawingAreaProxyCoordinatedGraphics {
        const drawing_area = try allocator.create(DrawingAreaProxyCoordinatedGraphics);
        drawing_area.* = .{
            .allocator = allocator,
            .web_page = page,
            .web_process_proxy = web_process_proxy,
            .discard_backing_store_timer = OneShotTimer.init(@ptrCast(drawing_area), discardBackingStoreTimerCallback),
        };
        return drawing_area;
    }

    pub fn destroy(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.isInAcceleratedCompositingMode())
            self.exitAcceleratedCompositingMode();

        if (self.backing_store) |backing_store| {
            backing_store.destroy();
            self.backing_store = null;
        }

        if (self.drawing_monitor) |drawing_monitor| {
            drawing_monitor.destroy();
            self.drawing_monitor = null;
        }

        self.allocator.destroy(self);
    }

    pub fn page(self: *const DrawingAreaProxyCoordinatedGraphics) ?*WebPageProxy {
        return self.web_page;
    }

    pub fn identifier(self: *const DrawingAreaProxyCoordinatedGraphics) u64 {
        return self.identifier_value;
    }

    pub fn size(self: *const DrawingAreaProxyCoordinatedGraphics) IntSize {
        if (self.web_page) |page_proxy|
            return page_proxy.viewSize();
        return .{};
    }

    pub fn isInAcceleratedCompositingMode(self: *const DrawingAreaProxyCoordinatedGraphics) bool {
        return self.layer_tree_context.identifier != 0;
    }

    pub fn paint(self: *DrawingAreaProxyCoordinatedGraphics, paint_context: PlatformPaintContextPtr, rect: IntRect, unpainted_region: *Region) void {
        unpainted_region.assignRect(rect) catch return;

        if (self.isInAcceleratedCompositingMode())
            return;

        if (self.backing_store == null and !self.forceUpdateIfNeeded())
            return;

        if (self.backing_store) |backing_store| {
            backing_store.paint(paint_context, rect);
            unpainted_region.subtract(.{
                .origin = .{},
                .size = backing_store.size(),
            });
        }

        self.discardBackingStoreSoon();
    }

    pub fn forceUpdateIfNeeded(self: *DrawingAreaProxyCoordinatedGraphics) bool {
        if (self.isInAcceleratedCompositingMode())
            return false;

        if (!self.web_process_proxy.hasConnection())
            return false;

        if (self.web_process_proxy.state() == .launching)
            return false;

        if (self.is_waiting_for_did_update_geometry)
            return false;

        const page_proxy = self.page() orelse return false;

        if (!page_proxy.isViewVisible())
            return false;

        self.in_force_update = true;
        defer self.in_force_update = false;

        return self.backing_store != null;
    }

    pub fn incorporateUpdate(self: *DrawingAreaProxyCoordinatedGraphics, update_info: UpdateInfo) void {
        if (self.isInAcceleratedCompositingMode())
            return;

        if (update_info.update_rect_bounds.isEmpty())
            return;

        if (self.backing_store == null or
            !self.backing_store.?.size().eql(update_info.view_size) or
            self.backing_store.?.deviceScaleFactor() != update_info.device_scale_factor)
        {
            if (self.backing_store) |existing_backing_store|
                existing_backing_store.destroy();

            self.backing_store = BackingStore.create(
                self.allocator,
                update_info.view_size,
                update_info.device_scale_factor,
            ) catch return;
        }

        if (self.in_force_update) {
            self.backing_store.?.incorporateUpdate(update_info);
            return;
        }

        const page_proxy = self.page() orelse return;

        var damage_region = Region.init(self.allocator);
        if (update_info.scroll_rect.isEmpty()) {
            for (update_info.update_rects) |rect|
                damage_region.unite(rect) catch {};
        } else {
            damage_region.assignRect(.{
                .origin = .{},
                .size = page_proxy.viewSize(),
            }) catch {};
        }

        self.backing_store.?.incorporateUpdate(update_info);
        page_proxy.setViewNeedsDisplay(damage_region);
    }

    pub fn displayNominalFramesPerSecond(self: *DrawingAreaProxyCoordinatedGraphics) ?FramesPerSecond {
        const page_proxy = self.page() orelse return null;
        const display_id = page_proxy.displayID() orelse return null;
        return page_proxy.nominalFramesPerSecondForDisplay(display_id);
    }

    pub fn sizeDidChange(self: *DrawingAreaProxyCoordinatedGraphics) void {
        const page_proxy = self.page() orelse return;

        if (!page_proxy.hasRunningProcess())
            return;

        if (self.is_waiting_for_did_update_geometry)
            return;

        self.sendUpdateGeometry();
    }

    pub fn deviceScaleFactorDidChange(self: *DrawingAreaProxyCoordinatedGraphics, completion_handler: CompletionHandler) void {
        if (self.page() == null) {
            completion_handler();
            return;
        }

        completion_handler();
    }

    pub fn setBackingStoreIsDiscardable(self: *DrawingAreaProxyCoordinatedGraphics, is_backing_store_discardable: bool) void {
        if (self.is_backing_store_discardable == is_backing_store_discardable)
            return;

        self.is_backing_store_discardable = is_backing_store_discardable;

        if (self.is_backing_store_discardable)
            self.discardBackingStoreSoon()
        else
            self.discard_backing_store_timer.stop();
    }

    pub fn adjustTransientZoom(_: *DrawingAreaProxyCoordinatedGraphics, _: f64, _: FloatPoint, _: FloatPoint) void {}

    pub fn commitTransientZoom(_: *DrawingAreaProxyCoordinatedGraphics, _: f64, _: FloatPoint) void {}

    pub fn enterAcceleratedCompositingModeWithIdentifier(
        self: *DrawingAreaProxyCoordinatedGraphics,
        _: u64,
        layer_tree_context: LayerTreeContext,
    ) void {
        self.enterAcceleratedCompositingMode(layer_tree_context);
    }

    pub fn update(self: *DrawingAreaProxyCoordinatedGraphics, _: u64, update_info: UpdateInfo) void {
        if (self.is_waiting_for_did_update_geometry and !update_info.view_size.eql(self.last_sent_size)) {
            return;
        }

        self.incorporateUpdate(update_info);
    }

    pub fn exitAcceleratedCompositingModeWithUpdate(
        self: *DrawingAreaProxyCoordinatedGraphics,
        _: u64,
        update_info: UpdateInfo,
    ) void {
        self.exitAcceleratedCompositingMode();
        self.incorporateUpdate(update_info);
    }

    pub fn updateAcceleratedCompositingModeWithIdentifier(
        self: *DrawingAreaProxyCoordinatedGraphics,
        _: u64,
        layer_tree_context: LayerTreeContext,
    ) void {
        self.updateAcceleratedCompositingMode(layer_tree_context);
    }

    pub fn alwaysUseCompositing(self: *const DrawingAreaProxyCoordinatedGraphics) bool {
        const page_proxy = self.page() orelse return false;
        return page_proxy.preferences().acceleratedCompositingEnabled() and page_proxy.preferences().forceCompositingMode();
    }

    pub fn enterAcceleratedCompositingMode(
        self: *DrawingAreaProxyCoordinatedGraphics,
        layer_tree_context: LayerTreeContext,
    ) void {
        if (self.isInAcceleratedCompositingMode()) {
            self.updateAcceleratedCompositingMode(layer_tree_context);
            return;
        }

        if (self.backing_store) |backing_store| {
            backing_store.destroy();
            self.backing_store = null;
        }

        self.layer_tree_context = layer_tree_context;

        if (self.page()) |page_proxy|
            page_proxy.enterAcceleratedCompositingMode(layer_tree_context);
    }

    pub fn exitAcceleratedCompositingMode(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (!self.isInAcceleratedCompositingMode())
            return;

        self.layer_tree_context = LayerTreeContext.empty();

        if (self.page()) |page_proxy|
            page_proxy.exitAcceleratedCompositingMode();
    }

    pub fn updateAcceleratedCompositingMode(
        self: *DrawingAreaProxyCoordinatedGraphics,
        layer_tree_context: LayerTreeContext,
    ) void {
        if (!self.isInAcceleratedCompositingMode())
            return;

        self.layer_tree_context = layer_tree_context;

        if (self.page()) |page_proxy|
            page_proxy.updateAcceleratedCompositingMode(layer_tree_context);
    }

    pub fn dispatchPresentationCallbacksAfterFlushingLayers(
        _: *DrawingAreaProxyCoordinatedGraphics,
        connection: *Connection,
        callback_ids: []const AsyncReplyID,
    ) void {
        for (callback_ids) |callback_id| {
            if (connection.takeAsyncReplyHandler(callback_id)) |callback|
                callback(null, null);
        }
    }

    pub fn sendUpdateGeometry(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.is_waiting_for_did_update_geometry)
            return;

        self.last_sent_size = self.size();
        self.is_waiting_for_did_update_geometry = true;
        self.didUpdateGeometry();
    }

    pub fn didUpdateGeometry(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (!self.is_waiting_for_did_update_geometry)
            return;

        self.is_waiting_for_did_update_geometry = false;

        if (!self.last_sent_size.eql(self.size()))
            self.sendUpdateGeometry();
    }

    pub fn discardBackingStoreSoon(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.backing_store == null or
            !self.is_backing_store_discardable or
            self.discard_backing_store_timer.isActive())
        {
            return;
        }

        self.discard_backing_store_timer.startOneShot(10 * std.time.ns_per_s);
    }

    pub fn discardBackingStore(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.backing_store) |backing_store| {
            backing_store.destroy();
            self.backing_store = null;
        } else {
            return;
        }
    }

    pub fn dispatchAfterEnsuringDrawing(
        self: *DrawingAreaProxyCoordinatedGraphics,
        callback_function: CompletionHandler,
    ) void {
        const page_proxy = self.page() orelse {
            callback_function();
            return;
        };

        if (!page_proxy.hasRunningProcess()) {
            callback_function();
            return;
        }

        if (self.drawing_monitor == null) {
            self.drawing_monitor = DrawingMonitor.create(
                self.allocator,
                @ptrCast(self),
                drawingMonitorStopCallback,
            ) catch {
                callback_function();
                return;
            };
        }

        self.drawing_monitor.?.start(callback_function);
    }
};

pub const DrawingMonitor = struct {
    allocator: std.mem.Allocator,
    timer: OneShotTimer,
    callback: ?CompletionHandler = null,

    pub fn create(
        allocator: std.mem.Allocator,
        context: *anyopaque,
        timer_callback: TimerCallback,
    ) !*DrawingMonitor {
        const monitor = try allocator.create(DrawingMonitor);
        monitor.* = .{
            .allocator = allocator,
            .timer = OneShotTimer.init(context, timer_callback),
        };
        return monitor;
    }

    pub fn destroy(self: *DrawingMonitor) void {
        if (self.callback) |callback|
            callback();
        self.stop();
        self.allocator.destroy(self);
    }

    pub fn start(self: *DrawingMonitor, callback: CompletionHandler) void {
        self.callback = callback;
        self.timer.startOneShot(0);
    }

    pub fn stop(self: *DrawingMonitor) void {
        self.timer.stop();

        if (self.callback) |callback| {
            self.callback = null;
            callback();
        }
    }
};

fn discardBackingStoreTimerCallback(context: *anyopaque) void {
    const drawing_area: *DrawingAreaProxyCoordinatedGraphics = @ptrCast(@alignCast(context));
    drawing_area.discardBackingStore();
}

fn drawingMonitorStopCallback(context: *anyopaque) void {
    const drawing_area: *DrawingAreaProxyCoordinatedGraphics = @ptrCast(@alignCast(context));
    if (drawing_area.drawing_monitor) |drawing_monitor|
        drawing_monitor.stop();
}
